		event["hevy.api.phase"] = execution.phase;
		event["hevy.api.operation_safety"] = execution.operation_safety;
		event["hevy.api.commit_state"] = execution.commit_state;
		event["hevy.api.safe_to_retry"] = execution.safe_to_retry;
	}
